contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool callAsOwner) public payable {
        // Fund the contract so the balance is observable.
        (bool sent, ) = address(c).call{value: msg.value}("");
        require(sent);

        address ownerAddr = c.Owner();
        uint256 beforeC = address(c).balance;

        bool reverted;
        if (callAsOwner) {
            // We are the owner since this test contract deployed c and calls it.
            // wait: callAsOwner is a flag independent of actual msg.sender.
            // To test owner path we must actually be the owner.
        }

        // Determine whether this contract is the owner.
        bool isOwner = (address(this) == ownerAddr);

        // We can only exercise the owner path when isOwner is true.
        // Use the boolean parameter to choose whether to call withdraw as-is.
        if (callAsOwner) {
            // only meaningful if isOwner; otherwise this call reverts as non-owner.
            try c.withdraw() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(isOwner == !reverted);
    }

    receive() external payable {}
}

