contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool ownerCalls) public payable {
        require(address(this).balance >= amount);

        // Fund c so its balance is nonzero and a transfer is observable.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint256 cBalBefore = address(c).balance;
        uint256 ownerBalBefore = c.Owner().balance;

        bool reverted;

        if (ownerCalls) {
            try c.withdraw() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Execute withdraw from a different sender using a fresh helper contract.
            NonOwnerCaller noc = new NonOwnerCaller(c);
            noc.callWithdraw();
            reverted = noc.reverted();
        }

        uint256 cBalAfter = address(c).balance;
        uint256 ownerBalAfter = c.Owner().balance;

        if (ownerCalls) {
            assert(!reverted);
            assert(cBalAfter == 0);
            assert(ownerBalAfter == ownerBalBefore + cBalBefore);
        } else {
            assert(reverted);
            assert(cBalAfter == cBalBefore);
            assert(ownerBalAfter == ownerBalBefore);
        }
    }

    receive() external payable {}
}

