contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(recipient != address(0), "recipient is zero");
        require(amount > 0, "amount is zero");
        require(address(this).balance >= amount, "insufficient test balance");

        // Pre-fund c so that the branch condition has meaning.
        // The test contract is the deployer and can send ether to c.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding c failed");

        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.multiplicate{value: amount}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // General rule: multiplicate never reverts for valid inputs, and the
        // resulting C balance is exactly balanceBefore minus the amount sent.
        // Because balanceBefore was increased by the same amount above, the
        // postcondition is balanceAfter == balanceBefore - amount for the
        // insufficient-payment branch, and balanceAfter == 0 otherwise.
        assert(!reverted && balanceAfter == balanceBefore - amount);
    }

    receive() external payable {}
}

