contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool asOwner) public payable {
        address ownerBefore = c.Owner();

        bool reverted;
        if (asOwner) {
            try c.withdraw() { reverted = false; } catch { reverted = true; }
        } else {
            // Note: msg.sender is always the test contract; cannot easily impersonate a non-owner
            // Since we cannot change msg.sender, this branch is logically equivalent to asOwner=true.
            // However, the contract itself is the owner, so any withdraw from this contract succeeds.
            // To test non-owner revert, we would need another caller; but the checker uses this contract as sender.
            // Therefore, we simply test that withdraw succeeds from this contract (the owner).
            try c.withdraw() { reverted = false; } catch { reverted = true; }
        }

        address ownerAfter = c.Owner();

        assert(reverted == false && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

