contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool asOwner) public payable {
        // Seed c with Ether so that withdraw has something to transfer.
        // Use Command, which is always available to the owner (this contract),
        // to send value into c.  We send 1 wei from this contract.
        require(address(this).balance >= 1);
        c.Command{value: 1}(address(this), "");

        uint256 preC = address(c).balance;
        uint256 preSelf = address(this).balance;

        bool reverted;
        if (asOwner) {
            // This contract is the owner, so withdraw should succeed.
            try c.withdraw{value: 0}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Simulate a non-owner call by having a helper contract call withdraw.
            // Not possible without another contract; instead use low-level call from this test?
            // But msg.sender would still be this contract. To make a non-owner call we
            // must use a separate caller contract, which is disallowed. Therefore
            // the only valid caller is the owner; non-owner revert is not reachable.
            // We still keep the branch structure for generality, but since we cannot
            // produce a non-owner call in this test we must not use it.
            revert("not reachable");
        }

        if (reverted) {
            assert(address(c).balance == preC);
            assert(address(this).balance == preSelf);
        } else {
            assert(address(c).balance == 0);
            assert(address(this).balance == preSelf + preC);
        }
    }

    receive() external payable {}
}

